["MINIBOSS_HYPERION_TITLE"]="Cronos",
["battleHyperionDescription"]="Cronos se oculta entre las instalaciones de la fábrica. ¡Debes hallarlo!",
["NAME_CYGNUS"]="CYGNUS",
["NAME_RAPTOR"]="RAPTOR",
